/** The providers the sign-in page offers, besides the password. */
export const socialProviders: readonly string[] = socialLogin ? providers.filter((p) => p !== "password") : []

interface Social {
  oauthUrl(provider: string, redirect?: string): string
  linkProvider(provider: string, redirect?: string): Promise<{ url: string }>
  unlinkProvider(provider: string): Promise<void>
  providers(o?: { signal?: AbortSignal }): Promise<{ provider: string; created_at: string }[]>
}

const social = () => api.identity[realmKey] as unknown as Social

const NAMES: Record<string, string> = { google: "Google", github: "GitHub" }

/** A provider's name, as people know it. */
export const providerName = (p: string) => NAMES[p] ?? p.charAt(0).toUpperCase() + p.slice(1)

/** A provider's mark: its letter in a circle for those without one here. */
