/** Why a sign-in with a provider came back without one, in words. */
export function socialProblem(code: string): string {
  switch (code) {
    case "linked_elsewhere":
      return t("socialLinkedElsewhere")
    case "account_exists":
      return t("socialAccountExists")
    case "email_missing":
      return t("socialEmailMissing")
    case "signup_closed":
      return t("socialSignupClosed")
    case "signup_incomplete":
      return t("socialSignupIncomplete")
  }
  return t("socialFailed")
}

/** Where the provider sends the browser back to: the sign-in page, which goes on. */
function back(redirect?: string): string {
  const to = afterSignIn(redirect)
  return `${base}login?social=1${to !== "/" ? `&redirect=${encodeURIComponent(to)}` : ""}`
}

/** The buttons of the providers, below the password's form (or alone). */
export function SocialButtons({ redirect, alone = false }: { redirect?: string; alone?: boolean }) {
  const [going, setGoing] = useState("")
  if (socialProviders.length === 0) return null
  return (
    <div className="flex flex-col gap-4">
      {!alone && (
        <div className="flex items-center gap-3 text-xs font-medium text-muted-foreground">
          <span className="h-px flex-1 bg-border" />
          {t("orContinueWith")}
          <span className="h-px flex-1 bg-border" />
        </div>
      )}
      <div className="flex gap-2">
        {socialProviders.map((p) => (
          <Button
            key={p}
            type="button"
            variant="outline"
            size="lg"
            className="flex-1"
            disabled={going !== ""}
            onClick={() => {
              setGoing(p)
              window.location.assign(social().oauthUrl(p, back(redirect)))
            }}
          >
            {going === p ? <Spinner /> : <ProviderMark provider={p} />}
            {socialProviders.length === 1 || alone ? t("continueWith", { name: providerName(p) }) : providerName(p)}
          </Button>
        ))}
      </div>
    </div>
  )
}

/**
 * Back from a provider (?social=1): with ?error=, why it failed; else the
 * session it opened, and on to the page asked for.
 */
export function useSocialReturn(search: { social?: unknown; error?: unknown; redirect?: string }): { error: string; busy: boolean } {
  const queryClient = useQueryClient()
  const navigate = useNavigate()
  const returning = Boolean(search.social) && !search.error
  const [busy, setBusy] = useState(returning)
  const [error, setError] = useState(typeof search.error === "string" ? socialProblem(search.error) : "")
  useEffect(() => {
    if (!returning) return
    queryClient
      .fetchQuery({ ...sessionQuery, staleTime: 0 })
      .then((session) => {
        if (!session) return setError(t("socialFailed"))
        announceSession("signed-in")
        navigate({ to: afterSignIn(search.redirect) as never, replace: true })
      })
      .catch((e) => setError(describe(e)))
      .finally(() => setBusy(false))
  }, [returning])
  return { error, busy }
}

const since: FieldMeta = { name: "since", label: "", kind: "datetime", required: false }

/** The providers of the account: connected or not, to connect or take off. */
export function ConnectedAccountsCard() {
  const queryClient = useQueryClient()
  const sensitive = useSensitive()
  const linked = useQuery({ queryKey: ["account", "providers"], queryFn: ({ signal }) => social().providers({ signal }) })
  const [going, setGoing] = useState("")
  const refresh = () => queryClient.invalidateQueries({ queryKey: ["account", "providers"] })
  return (
    <Card>
      <CardHeader>
        <CardTitle>{t("connectedAccounts")}</CardTitle>
        <CardDescription>{t("connectedAccountsHint")}</CardDescription>
      </CardHeader>
      <CardContent className="flex flex-col divide-y">
        {linked.isPending && [0, 1].map((i) => <Skeleton key={i} className="my-2 h-12 w-full" />)}
        {linked.isError && <p className="text-sm text-destructive">{describe(linked.error)}</p>}
        {linked.data &&
          socialProviders.map((p) => {
            const link = linked.data.find((l) => l.provider === p)
            return (
              <div key={p} className="flex items-center gap-3 py-3">
                <span className="flex size-10 items-center justify-center rounded-full border border-border">
                  <ProviderMark provider={p} className="size-5" />
                </span>
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-semibold">{providerName(p)}</p>
                  <p className="text-xs text-muted-foreground">{link ? t("connectedSince", { when: format(since, link.created_at) }) : t("notConnected")}</p>
                </div>
                {link ? (
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={async () => {
                      if (!(await ask(t("disconnectQ", { name: providerName(p) }), { description: t("disconnectHint") }))) return
                      try {
                        await sensitive(() => social().unlinkProvider(p), t("disconnected"))
                      } finally {
                        refresh()
                      }
                    }}
                  >
                    {t("disconnect")}
                  </Button>
                ) : (
                  <Button
                    variant="outline"
                    size="sm"
                    disabled={going !== ""}
                    onClick={async () => {
                      setGoing(p)
                      try {
                        const { url } = await social().linkProvider(p, `${base}settings?section=connected`)
                        window.location.assign(url)
                      } catch (e) {
                        setGoing("")
                        if (!(isApiError(e) && e.code === "reauthentication_required")) toast(describe(e), "error")
                        else await sensitive(() => Promise.reject(e), "")
                      }
                    }}
                  >
                    {going === p ? <Spinner /> : <ProviderMark provider={p} />} {t("connect")}
                  </Button>
                )}
              </div>
            )
          })}
      </CardContent>
    </Card>
  )
}
